import java.io.*;import javax.servlet.*;import javax.servlet.http.*;import java.util.UUID;public class S extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{javax.servlet.http.Part p=r.getPart("file");String name=p.getSubmittedFileName();String ext="";int i=name.lastIndexOf('.');if(i>0)ext=name.substring(i+1).toLowerCase();if(ext.equals("png")||ext.equals("jpg")||ext.equals("jpeg")){String n=UUID.randomUUID().toString()+"."+ext;p.write("uploads/"+n);s.getWriter().print("ok");}else s.getWriter().print("bad");}}